-- 05 — Empresas, marcas, endereços, categorias e o acervo Learning Studio
-- Gerado a partir do acervo do projeto. Pode ser executado novamente sem duplicar.

begin;

on conflict (id) do update set
  slug = excluded.slug,
  name = excluded.name,
  is_platform = excluded.is_platform,
  status = excluded.status,
  user_limit = excluded.user_limit,
  created_at = excluded.created_at;

on conflict (id) do update set
  organization_id = excluded.organization_id,
  favicon_url = excluded.favicon_url,
  banner_url = excluded.banner_url,
  dark_background_color = excluded.dark_background_color,
  dark_surface_color = excluded.dark_surface_color,
  dark_text_color = excluded.dark_text_color,
  logo_light_url = excluded.logo_light_url,
  logo_dark_url = excluded.logo_dark_url,
  primary_color = excluded.primary_color,
  secondary_color = excluded.secondary_color,
  accent_color = excluded.accent_color,
  background_color = excluded.background_color,
  surface_color = excluded.surface_color,
  text_color = excluded.text_color,
  environment_name = excluded.environment_name,
  welcome_title = excluded.welcome_title,
  welcome_message = excluded.welcome_message;

on conflict (id) do update set
  organization_id = excluded.organization_id,
  hostname = excluded.hostname,
  is_primary = excluded.is_primary;

on conflict (id) do update set
  slug = excluded.slug,
  name = excluded.name,
  description = excluded.description,
  sort_order = excluded.sort_order;

on conflict (id) do update set
  slug = excluded.slug,
  title = excluded.title,
  subtitle = excluded.subtitle,
  description = excluded.description,
  cover_url = excluded.cover_url,
  banner_url = excluded.banner_url,
  instructor_name = excluded.instructor_name,
  instructor_bio = excluded.instructor_bio,
  duration_minutes = excluded.duration_minutes,
  level = excluded.level,
  category_id = excluded.category_id,
  owner_org_id = excluded.owner_org_id,
  visibility = excluded.visibility,
  status = excluded.status,
  delivery_type = excluded.delivery_type,
  embed_url = excluded.embed_url,
  external_checkout_url = excluded.external_checkout_url,
  is_featured = excluded.is_featured,
  is_required = excluded.is_required,
  created_at = excluded.created_at,
  updated_at = excluded.updated_at;

on conflict (id) do update set
  course_id = excluded.course_id,
  title = excluded.title,
  description = excluded.description,
  sort_order = excluded.sort_order,
  created_at = excluded.created_at;

on conflict (id) do update set
  course_id = excluded.course_id,
  module_id = excluded.module_id,
  slug = excluded.slug,
  title = excluded.title,
  description = excluded.description,
  video_url = excluded.video_url,
  video_provider = excluded.video_provider,
  video_id = excluded.video_id,
  duration_seconds = excluded.duration_seconds,
  sort_order = excluded.sort_order,
  is_preview = excluded.is_preview,
  created_at = excluded.created_at;

on conflict (id) do update set
  course_id = excluded.course_id,
  provider = excluded.provider,
  embed_url = excluded.embed_url,
  created_at = excluded.created_at,
  updated_at = excluded.updated_at;

on conflict (organization_id, course_id) do update set
  course_id = excluded.course_id,
  is_visible = excluded.is_visible,
  created_at = excluded.created_at;

commit;
